UPDATE code_sessions
SET last_inbound_sequence_num = #{sequenceNum},
    updated_at = #{now}
WHERE uuid = #{codeSessionUUID}

UPDATE code_sessions
SET last_outbound_sequence_num = #{sequenceNum},
    updated_at = #{now}
WHERE uuid = #{codeSessionUUID}

UPDATE code_sessions
SET status = 'active',
    updated_at = #{now}
WHERE uuid = #{codeSessionUUID}
  AND status = 'initializing'
  AND deleted_at IS NULL
